public class ShipmentServerService : IShipmentService
{
    private static readonly List<Shipment> Shipments =
    [
        new() { Id = 1, TrackingNumber = "TRK-10001", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(2), RecipientName = "Alice Johnson", Description = "Electronics — 2 boxes" },
        new() { Id = 2, TrackingNumber = "TRK-10002", Origin = "Chicago, IL", Destination = "Houston, TX", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow, RecipientName = "Bob Smith", Description = "Furniture — 1 pallet" },
        new() { Id = 3, TrackingNumber = "TRK-10003", Origin = "Seattle, WA", Destination = "Miami, FL", Status = ShipmentStatus.Pending, ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(7), RecipientName = "Carol Davis", Description = "Medical supplies — 5 boxes" },
        new() { Id = 4, TrackingNumber = "TRK-10004", Origin = "Denver, CO", Destination = "Boston, MA", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow.AddDays(-1), RecipientName = "Dan Wilson", Description = "Auto parts — 3 crates" },
        new() { Id = 5, TrackingNumber = "TRK-10005", Origin = "Atlanta, GA", Destination = "Phoenix, AZ", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.UtcNow.AddDays(-4), EstimatedDelivery = DateTime.UtcNow.AddDays(3), RecipientName = "Eve Martinez", Description = "Clothing — 10 boxes" },
        new() { Id = 6, TrackingNumber = "TRK-10006", Origin = "San Francisco, CA", Destination = "Dallas, TX", Status = ShipmentStatus.PickedUp, ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(4), RecipientName = "Frank Lee", Description = "Food products — refrigerated" },
        new() { Id = 7, TrackingNumber = "TRK-10007", Origin = "Portland, OR", Destination = "Nashville, TN", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-2), EstimatedDelivery = DateTime.UtcNow.AddDays(3), RecipientName = "Grace Kim", Description = "Books — 4 boxes" },
        new() { Id = 8, TrackingNumber = "TRK-10008", Origin = "Minneapolis, MN", Destination = "Charlotte, NC", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(4), RecipientName = "Henry Brown", Description = "Office equipment — 2 pallets" },
    ];

    private static readonly Lock Lock = new();

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        lock (Lock)
        {
            return Task.FromResult(Shipments.ToList());
        }
    }

    public Task<List<Shipment>> GetShipmentsByStatusAsync(ShipmentStatus? status)
    {
        lock (Lock)
        {
            var result = status.HasValue
                ? Shipments.Where(s => s.Status == status.Value).ToList()
                : Shipments.ToList();
            return Task.FromResult(result);
        }
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        lock (Lock)
        {
            var shipment = Shipments.FirstOrDefault(
                s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
            return Task.FromResult(shipment);
        }
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        lock (Lock)
        {
            var shipment = Shipments.FirstOrDefault(s => s.Id == id);
            if (shipment is not null)
            {
                shipment.Status = newStatus;
            }
        }
        return Task.CompletedTask;
    }
}

